 "content": "def transform(grid):
    """Extend each diagonal run of length >= 2 until blocked or at the edge."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Each adjacent equal-color diagonal pair defines an axis. Continue both
    # ends, painting only background cells; other colors stop the ray.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if 0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color:
