 "content": "def transform(grid):
    """Extend isolated ends of diagonal same-color runs through background."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def free_orthogonally(r, c):
        return all(not (0 <= r + dr < h and 0 <= c + dc < w)
                   or grid[r + dr][c + dc] == background
                   for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)))

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                r2, c2 = r + dr, c + dc
                if not (0 <= r2 < h and 0 <= c2 < w and grid[r2][c2] == color):
                    continue
                # Extend outward from each end only when it is not attached
                # orthogonally to another foreground feature; stop at obstacles.
                for er, ec, sr, sc in ((r, c, -dr, -dc), (r2, c2, dr, dc)):
                    if not free_orthogonally(er, ec):
                        continue
                    rr, cc = er + sr, ec + sc
                    while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == background:
                        out[rr][cc] = color
                        rr += sr
                        cc += sc
    return out
